ee.Initialize(project=__import__('os').environ.get('EE_PROJECT','ee-abao9474'));d=pd.read_parquet(__import__('os').environ.get('AQUATIC_PANEL',str(Path(__file__).resolve().parents[1]/'data/raw/china_aquatic_buffering_panel_v2.parquet')));g=d[d.valid_model_both_y].drop_duplicates('grid_id')[['grid_id','lon','lat']].copy();g['zone']=np.floor((g.lon+180)/6).astype(int)+1;gsw=ee.Image('JRC/GSW1_4/GlobalSurfaceWater');occ=gsw.select('occurrence').unmask(0);sea=gsw.select('seasonality').unmask(0);wc=ee.ImageCollection('ESA/WorldCover/v200').first().select('Map');veg=wc.remap([10,20,30,40,90,95,100],[1]*7,0).eq(1).And(occ.eq(0));area=ee.Image.pixelArea();rows=[]
